<?php require '../../includes/config.php';require '../../includes/layout.php';require_login(['student']);$uid=$_SESSION['user']['id'];$stmt=$conn->prepare('SELECT t.*,d.name department_name FROM tickets t LEFT JOIN departments d ON d.id=t.department_id WHERE t.student_id=? ORDER BY t.created_at DESC');$stmt->bind_param('i',$uid);$stmt->execute();$tickets=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);student_shell('My Complaints','tickets');?><div class="page-header"><h2>My Complaints</h2></div><?php if($ref=flash('ticket_ref'))echo'<div class="alert alert-success">Ticket submitted successfully. Your reference number is <b>'.e($ref).'</b>. Keep it to track this complaint.</div>';?><div class="content-card"><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Subject</th><th>Topic</th><th>Department</th><th>Status</th><th>Submitted</th></tr></thead><tbody><?php if(!$tickets)echo'<tr><td colspan="6">You have not submitted any complaints.</td></tr>';foreach($tickets as $t){$slug=strtolower(str_replace(' ','-',$t['status']));echo'<tr><td><a href="view-ticket.php?ref='.urlencode($t['ref_number']).'"><b>'.e($t['ref_number']).'</b></a></td><td>'.e($t['subject']).'</td><td>'.e($t['topic']).'</td><td>'.e($t['department_name']?:'Pending routing').'</td><td><span class="badge badge-'.$slug.'">'.e($t['status']).'</span></td><td>'.e(date('d M Y',strtotime($t['created_at']))).'</td></tr>';}?><tr></tbody></table></div></div><?php dashboard_footer(); ?>